query:
CREATE TABLE `activityCategories` (
	`id` int AUTO_INCREMENT NOT NULL,
	`name` varchar(255) NOT NULL,
	`description` text,
	`icon` text,
	`isActive` boolean NOT NULL DEFAULT true,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `activityCategories_id` PRIMARY KEY(`id`),
	CONSTRAINT `activityCategories_name_unique` UNIQUE(`name`)
);
CREATE TABLE `activityHeatmap` (
	`id` int AUTO_INCREMENT NOT NULL,
	`date` datetime NOT NULL,
	`latitude` decimal(11,8) NOT NULL,
	`longitude` decimal(11,8) NOT NULL,
	`intensity` int,
	`activityCount` int,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `activityHeatmap_id` PRIMARY KEY(`id`)
);
CREATE TABLE `kpis` (
	`id` int AUTO_INCREMENT NOT NULL,
	`sdgGoalId` int NOT NULL,
	`name` varchar(255) NOT NULL,
	`description` text,
	`targetValue` decimal(10,2),
	`unit` varchar(50),
	`isActive` boolean NOT NULL DEFAULT true,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `kpis_id` PRIMARY KEY(`id`)
);
CREATE TABLE `sdgGoals` (
	`id` int AUTO_INCREMENT NOT NULL,
	`goalNumber` int NOT NULL,
	`title` varchar(255) NOT NULL,
	`description` text,
	`color` varchar(7) NOT NULL,
	`icon` text,
	`isActive` boolean NOT NULL DEFAULT true,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `sdgGoals_id` PRIMARY KEY(`id`),
	CONSTRAINT `sdgGoals_goalNumber_unique` UNIQUE(`goalNumber`)
);
CREATE TABLE `supervisorConfirmations` (
	`id` int AUTO_INCREMENT NOT NULL,
	`attendanceId` int NOT NULL,
	`staffUserId` int NOT NULL,
	`supervisorUserId` int NOT NULL,
	`supervisorName` varchar(255) NOT NULL,
	`supervisorPhone` varchar(20) NOT NULL,
	`digitalSignature` text,
	`privateRemarks` text,
	`remarksIv` varchar(32),
	`confirmedAt` timestamp NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `supervisorConfirmations_id` PRIMARY KEY(`id`)
);
ALTER TABLE `attendance` ADD `amStartTime` datetime;
ALTER TABLE `attendance` ADD `amEndTime` datetime;
ALTER TABLE `attendance` ADD `pmStartTime` datetime;
ALTER TABLE `attendance` ADD `pmEndTime` datetime;
ALTER TABLE `attendance` ADD `workModality` enum('nairobi_office','homa_bay_office','field','remote');
ALTER TABLE `attendance` ADD `activityCategoryId` int;
ALTER TABLE `attendance` ADD `sdgGoalId` int;
ALTER TABLE `attendance` ADD `program` varchar(255);
ALTER TABLE `attendance` ADD `kpiId` int;
ALTER TABLE `attendance` ADD `taskDescription` text;
ALTER TABLE `attendance` ADD `evidenceUploadKey` text;
ALTER TABLE `attendance` ADD `staffRemarks` text;
ALTER TABLE `attendance` ADD `isApproved` boolean DEFAULT false NOT NULL;
ALTER TABLE `attendance` ADD `approvedBy` int;
ALTER TABLE `attendance` ADD `approvedAt` timestamp;

